/* --- glass tokens --- */
const glass = {
  background: "rgba(255,250,245,0.12)",
  backdropFilter: "blur(24px)",
  WebkitBackdropFilter: "blur(24px)",
  border: "1px solid rgba(255,250,245,0.25)",
  borderRadius: 20,
};
const glassDark = {
  background: "rgba(30,14,10,0.45)",
  backdropFilter: "blur(20px)",
  WebkitBackdropFilter: "blur(20px)",
  border: "1px solid rgba(255,250,245,0.12)",
  borderRadius: 20,
};
const VINO = "#6E1E33";
const CREAM = "#F4EEE3";
const textMuted = "rgba(244,238,227,0.55)";

async function resizeImage(file, maxSide, quality) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(new Error("No se pudo leer"));
    reader.onload = () => {
      const img = new Image();
      img.onerror = () => reject(new Error("Imagen inválida"));
      img.onload = () => {
        const scale = Math.min(1, maxSide / Math.max(img.width, img.height));
        const canvas = document.createElement("canvas");
        canvas.width = Math.round(img.width * scale);
        canvas.height = Math.round(img.height * scale);
        canvas.getContext("2d").drawImage(img, 0, 0, canvas.width, canvas.height);
        resolve(canvas.toDataURL("image/jpeg", quality));
      };
      img.src = reader.result;
    };
    reader.readAsDataURL(file);
  });
}

const toB64 = (d) => d.split(",")[1];

async function copyText(text, setFlag) {
  try { await navigator.clipboard.writeText(text); } catch {
    const t = document.createElement("textarea"); t.value = text;
    document.body.appendChild(t); t.select(); document.execCommand("copy"); document.body.removeChild(t);
  }
  setFlag(true); setTimeout(() => setFlag(false), 1800);
}

async function callClaude(messages, maxTokens = 1400) {
  const res = await fetch("/api/claude", {
    method: "POST", headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ model: "claude-sonnet-4-6", max_tokens: maxTokens, messages }),
  });
  const data = await res.json();
  if (!res.ok || data.error) {
    const msg = data?.error?.message || data?.error?.type || JSON.stringify(data?.error) || "HTTP " + res.status;
    throw new Error("API: " + msg);
  }
  if (!data.content || !Array.isArray(data.content)) {
    throw new Error("Respuesta inesperada: " + JSON.stringify(data).slice(0, 300));
  }
  return data.content.filter((b) => b.type === "text").map((b) => b.text).join("\n").trim();
}

/* --- micro ui --- */
function Pill({ children, active, onClick, vino }) {
  return (
    <button onClick={onClick} style={{
      background: active ? (vino ? VINO : "rgba(255,250,245,0.25)") : "rgba(255,250,245,0.08)",
      border: active ? (vino ? `1px solid ${VINO}` : "1px solid rgba(255,250,245,0.4)") : "1px solid rgba(255,250,245,0.14)",
      color: CREAM, borderRadius: 999, padding: "7px 16px",
      fontFamily: "'Archivo Narrow', sans-serif", fontSize: 12,
      letterSpacing: "0.08em", textTransform: "uppercase",
      cursor: "pointer", backdropFilter: "blur(8px)", WebkitBackdropFilter: "blur(8px)",
      transition: "all 0.18s",
    }}>{children}</button>
  );
}

function BtnPrimary({ onClick, disabled, children }) {
  return (
    <button onClick={onClick} disabled={disabled} style={{
      background: disabled ? "rgba(110,30,51,0.25)" : VINO,
      color: disabled ? "rgba(244,238,227,0.35)" : CREAM,
      border: "none", borderRadius: 999, padding: "10px 22px",
      fontFamily: "'Archivo Narrow', sans-serif", fontSize: 13,
      letterSpacing: "0.1em", textTransform: "uppercase",
      cursor: disabled ? "default" : "pointer",
    }}>{children}</button>
  );
}

function BtnGhost({ onClick, children, red }) {
  return (
    <button onClick={onClick} style={{
      background: "rgba(255,250,245,0.07)",
      border: red ? `1px solid rgba(110,30,51,0.5)` : "1px solid rgba(255,250,245,0.18)",
      color: red ? "#c97a92" : CREAM,
      borderRadius: 999, padding: "9px 18px",
      fontFamily: "'Archivo Narrow', sans-serif", fontSize: 12,
      letterSpacing: "0.08em", textTransform: "uppercase",
      cursor: "pointer", backdropFilter: "blur(8px)", WebkitBackdropFilter: "blur(8px)",
    }}>{children}</button>
  );
}

function CopyBtn({ text, label = "Copiar" }) {
  const [ok, setOk] = useState(false);
  return (
    <button onClick={() => copyText(text, setOk)} style={{
      background: ok ? "rgba(46,110,78,0.6)" : "rgba(34,29,27,0.7)",
      color: CREAM, border: "1px solid rgba(255,250,245,0.15)",
      borderRadius: 999, padding: "7px 14px",
      fontFamily: "'Archivo Narrow', sans-serif", fontSize: 11,
      letterSpacing: "0.08em", textTransform: "uppercase", cursor: "pointer",
    }}>{ok ? "Copiado ✓" : label}</button>
  );
}

function Label({ children }) {
  return <span style={{ display: "block", fontFamily: "'Archivo Narrow', sans-serif", fontSize: 10, letterSpacing: "0.16em", textTransform: "uppercase", color: textMuted, marginBottom: 6 }}>{children}</span>;
}

function GlassInput({ value, onChange, placeholder, multiline, rows }) {
  const base = {
    width: "100%", boxSizing: "border-box",
    background: "rgba(255,250,245,0.07)",
    border: "1px solid rgba(255,250,245,0.16)",
    borderRadius: 12, padding: "10px 14px",
    fontFamily: "'Archivo', sans-serif", fontSize: 13,
    color: CREAM, outline: "none", resize: multiline ? "vertical" : undefined,
  };
  return multiline
    ? <textarea value={value} onChange={onChange} placeholder={placeholder} rows={rows || 4} style={{ ...base, minHeight: rows ? undefined : 80 }} />
    : <input value={value} onChange={onChange} placeholder={placeholder} style={base} />;
}

function GlassSelect({ value, onChange, children }) {
  return (
    <select value={value} onChange={onChange} style={{
      width: "100%", boxSizing: "border-box",
      background: "rgba(30,14,10,0.6)", backdropFilter: "blur(12px)",
      border: "1px solid rgba(255,250,245,0.16)",
      borderRadius: 12, padding: "10px 14px",
      fontFamily: "'Archivo', sans-serif", fontSize: 13,
      color: CREAM, outline: "none", appearance: "none",
    }}>{children}</select>
  );
}

function CodeBlock({ text, maxH = 180 }) {
  const [exp, setExp] = useState(false);
  return (
    <div>
      <pre onClick={() => setExp(!exp)} style={{
        margin: 0, background: "rgba(20,8,5,0.7)", backdropFilter: "blur(8px)",
        color: "#E8D5B0", padding: "12px 14px", fontSize: 11.5,
        fontFamily: "ui-monospace,Menlo,monospace",
        whiteSpace: "pre-wrap", wordBreak: "break-word",
        maxHeight: exp ? "none" : maxH, overflow: "hidden", cursor: "pointer",
        borderRadius: 12, borderLeft: `3px solid ${VINO}`,
      }}>{text}</pre>
      <button onClick={() => setExp(!exp)} style={{ background: "none", border: "none", color: textMuted, fontSize: 11, cursor: "pointer", padding: "4px 2px", fontFamily: "'Archivo Narrow', sans-serif", letterSpacing: "0.06em" }}>
        {exp ? "▲ Contraer" : "▼ Ver completo"}
      </button>
    </div>
  );
}

