function ImportModal({ onImport, onClose }) {
  const [text, setText] = useState("");
  const [err, setErr] = useState("");
  const doImport = () => {
    setErr("");
    try {
      const raw = JSON.parse(text.trim());
      const arr = Array.isArray(raw) ? raw : raw.entradas || raw.items || [];
      if (!arr.length) { setErr("No se encontraron entradas."); return; }
      const mapped = arr.map((e) => ({ id: uid(), tipo: e.tipo||"prompt", titulo: e.titulo||e.title||e.archivo_imagen||"Sin título", categoria: e.categoria||"", imagen: e.imagen||e.image||null, json_estilo: e.json_estilo?(typeof e.json_estilo==="string"?e.json_estilo:JSON.stringify(e.json_estilo,null,2)):null, prompt_original: e.prompt_original||e.prompt||null, prompt_recreacion: e.prompt_recreacion||null, createdAt: Date.now() }));
      onImport(mapped); onClose();
    } catch(e) { setErr("JSON inválido: "+e.message); }
  };
  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(20,8,5,0.8)", zIndex: 200, display: "flex", alignItems: "center", justifyContent: "center", padding: 20, backdropFilter: "blur(6px)" }}>
      <div style={{ ...glass, width: "100%", maxWidth: 540, padding: 24 }}>
        <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 16 }}>
          <h2 style={{ margin: 0, fontFamily: "'Archivo', sans-serif", fontWeight: 800, fontSize: 20, color: CREAM }}>Importar tu biblioteca</h2>
          <button onClick={onClose} style={{ background: "none", border: "none", color: textMuted, fontSize: 22, cursor: "pointer" }}>×</button>
        </div>
        <p style={{ fontFamily: "'Archivo', sans-serif", fontSize: 13, color: textMuted, margin: "0 0 12px", lineHeight: 1.5 }}>Pega aquí el contenido de tu archivo <strong style={{color:CREAM}}>biblioteca.json</strong> generado por Claude Code.</p>
        <GlassInput multiline value={text} onChange={(e)=>setText(e.target.value)} placeholder="[...]" rows={8}/>
        {err && <p style={{ color: "#ff8a8a", fontFamily: "'Archivo', sans-serif", fontSize: 13, margin: "8px 0" }}>{err}</p>}
        <div style={{ display: "flex", gap: 10, marginTop: 14 }}>
          <BtnPrimary disabled={!text.trim()} onClick={doImport}>Importar</BtnPrimary>
          <BtnGhost onClick={onClose}>Cancelar</BtnGhost>
        </div>
      </div>
    </div>
  );
}

/* --- banco --- */
function Banco({ entries, addEntry, importEntries, deleteEntry }) {
  const [tipoFilter, setTipoFilter] = useState("todos");
  const [catFilter, setCatFilter] = useState("todas");
  const [search, setSearch] = useState("");
  const [showAdd, setShowAdd] = useState(false);
  const [showImport, setShowImport] = useState(false);
  const cats = tipoFilter==="referencia"?CATS_REF:tipoFilter==="prompt"?CATS_PROMPT:ALL_CATS;
  const visible = entries.filter((e) => {
    if (tipoFilter!=="todos"&&e.tipo!==tipoFilter) return false;
    if (catFilter!=="todas"&&e.categoria!==catFilter) return false;
    const q = search.toLowerCase();
    if (q&&!e.titulo.toLowerCase().includes(q)&&!(e.prompt_original||"").toLowerCase().includes(q)&&!(e.json_estilo||"").toLowerCase().includes(q)) return false;
    return true;
  });
  return (
    <div>
      {showAdd && <AddModal onSave={(e)=>{addEntry(e);setShowAdd(false);}} onClose={()=>setShowAdd(false)} />}
      {showImport && <ImportModal onImport={importEntries} onClose={()=>setShowImport(false)} />}
      <div style={{ ...glass, padding: "16px 18px", marginBottom: 16 }}>
        <div style={{ display: "flex", flexWrap: "wrap", gap: 8, marginBottom: 12, alignItems: "center" }}>
          {["todos","prompt","referencia"].map((f) => <Pill key={f} active={tipoFilter===f} onClick={()=>{setTipoFilter(f);setCatFilter("todas");}} vino={tipoFilter===f}>{f==="todos"?"Todo":f==="prompt"?"Prompts":"Inspiraciones"}</Pill>)}
          <span style={{ marginLeft: "auto", fontFamily: "'Archivo Narrow', sans-serif", fontSize: 11, color: textMuted }}>{visible.length}/{entries.length}</span>
        </div>
        {tipoFilter!=="todos" && (
          <div style={{ display: "flex", flexWrap: "wrap", gap: 6, marginBottom: 12 }}>
            <Pill active={catFilter==="todas"} onClick={()=>setCatFilter("todas")}>Todas</Pill>
            {cats.map((c) => <Pill key={c.id} active={catFilter===c.id} onClick={()=>setCatFilter(c.id)}>{c.emoji} {c.label}</Pill>)}
          </div>
        )}
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
          <input value={search} onChange={(e)=>setSearch(e.target.value)} placeholder="Busca por nombre, estilo o categoría…" style={{ flex: 1, minWidth: 160, background: "rgba(255,250,245,0.07)", border: "1px solid rgba(255,250,245,0.16)", borderRadius: 999, padding: "9px 16px", fontFamily: "'Archivo', sans-serif", fontSize: 13, color: CREAM, outline: "none" }} />
          <BtnPrimary onClick={()=>setShowAdd(true)}>+ Nueva</BtnPrimary>
          <BtnGhost onClick={()=>setShowImport(true)} red>Importar biblioteca</BtnGhost>
        </div>
      </div>
      {visible.length===0
        ? <div style={{ ...glass, padding: "52px 24px", textAlign: "center", fontFamily: "'Archivo', sans-serif", fontSize: 15, color: textMuted, lineHeight: 1.7 }}>{entries.length===0?"Tu biblioteca está vacía. Empieza analizando una imagen.":"Nada por aquí. Prueba con otra búsqueda."}</div>
        : <div style={{ columns: "240px", columnGap: 14 }}>{visible.map((e) => <EntryCard key={e.id} entry={e} onDelete={deleteEntry} />)}</div>}
    </div>
  );
}

/* --- asistente --- */
const QUICK = ["Eliminar texto","Cambiar fondo","Agregar texto","Cambiar paleta","Quitar elemento","Efecto de luz","Cambiar producto","Mejorar acabado"];

function Asistente({ addEntry }) {
  const [refImg,setRefImg]=useState(null);
  const [refImgApi,setRefImgApi]=useState(null);
  const [refCat,setRefCat]=useState("");
  const [refJson,setRefJson]=useState("");
  const [refPrompt,setRefPrompt]=useState("");
  const [loadRef,setLoadRef]=useState(false);
  const [errRef,setErrRef]=useState("");
  const [savedRef,setSavedRef]=useState(false);
  const [editImg,setEditImg]=useState(null);
  const [editImgApi,setEditImgApi]=useState(null);
  const [editCat,setEditCat]=useState("");
  const [promptTxt,setPromptTxt]=useState("");
  const [changes,setChanges]=useState([]);
  const [custom,setCustom]=useState("");
  const [editResult,setEditResult]=useState("");
  const [loadEdit,setLoadEdit]=useState(false);
  const [errEdit,setErrEdit]=useState("");
  const [savedEdit,setSavedEdit]=useState(false);
  const [loadingText,setLoadingText]=useState(false);

  const loadImg = async (e, setS, setBig) => {
    const f = e.target.files?.[0]; if (!f) return;
    try { setS(await resizeImage(f,500,0.75)); setBig(await resizeImage(f,800,0.72)); } catch(err){alert(err.message);}
  };

  const loadEditImg = async (e) => {
    const f = e.target.files?.[0]; if (!f) return;
    try {
      const small = await resizeImage(f,500,0.75);
      const big = await resizeImage(f,800,0.72);
      setEditImg(small);
      setEditImgApi(big);
      setPromptTxt("");
      setLoadingText(true);
      try {
        const extracted = await callClaude([{role:"user",content:[
          {type:"image",source:{type:"base64",media_type:"image/jpeg",data:toB64(big)}},
          {type:"text",text:"Esta imagen puede tener texto de un prompt de generación de imágenes escrito en ella (normalmente en la parte inferior). Si encuentras texto de prompt: 1) Extráelo completo y exacto, 2) Tradúcelo al español si está en otro idioma. Si no hay texto de prompt visible, responde solo: SIN_PROMPT. Responde ÚNICAMENTE con el texto del prompt en español, sin explicaciones ni comillas."}
        ]}], 800);
        if (!extracted.includes("SIN_PROMPT")) {
          setPromptTxt(extracted.trim());
        }
      } catch(err){ /* si falla la extracción, el usuario puede escribirlo manual */ }
      setLoadingText(false);
    } catch(err){alert(err.message);}
  };

  const extractRef = async () => {
    if (!refImgApi) return;
    setLoadRef(true); setErrRef(""); setRefJson(""); setRefPrompt(""); setSavedRef(false);
    try {
      const text = await callClaude([{role:"user",content:[
        {type:"image",source:{type:"base64",media_type:"image/jpeg",data:toB64(refImgApi)}},
        {type:"text",text:"Analiza esta imagen de referencia. Haz dos cosas:\n\n1. JSON con: tipo_de_pieza, composicion, paleta_de_colores (hex), iluminacion, tipografia, elementos_principales, texturas_y_efectos, estilo_fotografico, mood.\n\n2. PLANTILLA de prompt en español para ChatGPT para recrear este estilo. Usa (xxx — instrucción) en elementos de contenido a personalizar. Estilo se describe con detalle sin marcadores.\n\nFormato exacto:\n---JSON---\n{json}\n---PROMPT---\n{plantilla}"}
      ]}],1800);
      const jm = text.match(/---JSON---\s*([\s\S]*?)---PROMPT---/);
      const pm = text.match(/---PROMPT---\s*([\s\S]*?)$/);
      setRefJson(jm?jm[1].trim().replace(/```json|```/g,"").trim():text);
      setRefPrompt(pm?pm[1].trim():"");
    } catch(err){setErrRef("Error: "+err.message);}
    setLoadRef(false);
  };

  const toggleChange = (c) => setChanges((p)=>p.includes(c)?p.filter((x)=>x!==c):[...p,c]);

  const generateEdit = async () => {
    if (!editImgApi) return;
    setLoadEdit(true); setErrEdit(""); setEditResult(""); setSavedEdit(false);
    const all = [...changes, custom.trim()].filter(Boolean);
    try {
      const text = await callClaude([{role:"user",content:[
        {type:"image",source:{type:"base64",media_type:"image/jpeg",data:toB64(editImgApi)}},
        {type:"text",text:"Foto a editar en ChatGPT.\n\n"+(promptTxt?"Prompt original:\n\""+promptTxt+"\"\n\n":"")+(refJson?"Estilo de referencia:\n"+refJson+"\n\n":"")+(all.length?"Cambios:\n- "+all.join("\n- ")+"\n\n":"")+"Escribe PLANTILLA de prompt en español para ChatGPT. Usa (xxx — instrucción) en contenido a personalizar. Estilo se describe completo. Solo la plantilla."}
      ]}],1200);
      setEditResult(text);
    } catch(err){setErrEdit("Error: "+err.message);}
    setLoadEdit(false);
  };

  const UpBox = ({img, onChange, label}) => (
    <label style={{display:"block",border:"1.5px dashed rgba(110,30,51,0.5)",borderRadius:16,cursor:"pointer",background:img?"transparent":"rgba(110,30,51,0.07)",marginBottom:12,overflow:"hidden"}}>
      {img?<img src={img} alt="" style={{width:"100%",maxHeight:250,objectFit:"contain",display:"block",background:"rgba(20,8,5,0.5)"}}/>
        :<div style={{padding:"28px 16px",textAlign:"center",fontFamily:"'Archivo',sans-serif",fontSize:14,color:"rgba(244,238,227,0.4)"}}>{label}</div>}
      <input type="file" accept="image/*" onChange={onChange} style={{display:"none"}}/>
    </label>
  );

  const SaveBtn = ({saved,onSave}) => (
    <button onClick={onSave} disabled={saved} style={{background:"none",border:saved?"1px solid rgba(46,110,78,0.6)":"1px solid rgba(255,250,245,0.2)",color:saved?"#7ec89a":CREAM,borderRadius:999,padding:"7px 14px",fontFamily:"'Archivo Narrow',sans-serif",fontSize:11,letterSpacing:"0.08em",textTransform:"uppercase",cursor:saved?"default":"pointer"}}>
      {saved?"Guardado en tu biblioteca ✓":"Guardar en mi biblioteca"}
    </button>
  );

  const Step = ({n,title,sub,children}) => (
    <div style={{...glassDark,padding:22,marginBottom:0}}>
      <div style={{display:"flex",gap:14,alignItems:"baseline",marginBottom:18}}>
        <span style={{fontFamily:"'Archivo',sans-serif",fontWeight:800,fontSize:44,color:"rgba(110,30,51,0.7)",lineHeight:1}}>{n}</span>
        <div><h3 style={{margin:0,fontFamily:"'Archivo',sans-serif",fontWeight:700,fontSize:17,color:CREAM}}>{title}</h3><p style={{margin:"4px 0 0",fontFamily:"'Archivo',sans-serif",fontSize:13,color:textMuted,lineHeight:1.5}}>{sub}</p></div>
      </div>
      {children}
    </div>
  );

  return (
    <div style={{display:"grid",gap:20}}>
      <Step n="01" title="¿Qué tiene esta imagen que te gusta?" sub="Sube una referencia visual y MUSEMAP te ayuda a entender por qué funciona: sus colores, composición, letras, sensación general y detalles clave para crear algo nuevo con ese estilo.">
        <UpBox img={refImg} onChange={(e)=>loadImg(e,setRefImg,setRefImgApi)} label="Subir mi referencia"/>
        <div style={{marginBottom:12}}><Label>Categoría</Label>
          <GlassSelect value={refCat} onChange={(e)=>setRefCat(e.target.value)}>
            <option value="" style={{background:"#1a0a07"}}>¿Dónde quieres guardarla?</option>
            {CATS_REF.map((c)=><option key={c.id} value={c.id} style={{background:"#1a0a07"}}>{c.emoji} {c.label}</option>)}
          </GlassSelect>
        </div>
        <BtnPrimary disabled={!refImgApi||loadRef} onClick={extractRef}>{loadRef?"⏳ Analizando tu imagen…":"Descubrir su estilo"}</BtnPrimary>
        {errRef&&<p style={{color:"#ff8a8a",fontFamily:"'Archivo',sans-serif",fontSize:13,margin:"10px 0 0"}}>{errRef}</p>}
        {refJson&&<div style={{marginTop:16,display:"flex",flexDirection:"column",gap:12}}>
          <div><Label>El mapa visual de tu referencia</Label><CodeBlock text={refJson}/></div>
          {refPrompt&&<div><Label>Tus instrucciones listas para crear</Label><CodeBlock text={refPrompt} maxH={160}/></div>}
          <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
            <CopyBtn text={refJson} label="Copiar mapa visual"/>
            {refPrompt&&<CopyBtn text={refPrompt} label="Copiar instrucciones"/>}
            <SaveBtn saved={savedRef} onSave={()=>{addEntry({id:uid(),tipo:"referencia",titulo:"Referencia "+new Date().toLocaleDateString("es-ES"),categoria:refCat,imagen:refImg,json_estilo:refJson,prompt_original:null,prompt_recreacion:refPrompt,createdAt:Date.now()});setSavedRef(true);}}/>
          </div>
        </div>}
      </Step>

      <Step n="02" title="¿Tienes una imagen con instrucciones escritas?" sub="MUSEMAP lee el texto por ti, lo traduce si hace falta y lo convierte en una plantilla reutilizable para crear con tus propios elementos.">
        <UpBox img={editImg} onChange={loadEditImg} label="Subir imagen con texto"/>
        {loadingText&&<p style={{fontFamily:"'Archivo',sans-serif",fontSize:12,color:"rgba(244,238,227,0.5)",margin:"0 0 10px"}}>Leyendo las instrucciones de tu imagen…</p>}
        <div style={{marginBottom:12}}><Label>Categoría</Label>
          <GlassSelect value={editCat} onChange={(e)=>setEditCat(e.target.value)}>
            <option value="" style={{background:"#1a0a07"}}>¿Dónde quieres guardarla?</option>
            {CATS_PROMPT.map((c)=><option key={c.id} value={c.id} style={{background:"#1a0a07"}}>{c.emoji} {c.label}</option>)}
          </GlassSelect>
        </div>
        <div style={{marginBottom:12}}><Label>Prompt original {loadingText?"— leyendo imagen…":promptTxt?"— Esto encontré en la imagen":"— No encontré texto en esta imagen. Prueba con una captura más clara o escribe aquí las instrucciones si las tienes."}</Label><GlassInput multiline value={promptTxt} onChange={(e)=>setPromptTxt(e.target.value)} placeholder="No encontré texto en esta imagen. Prueba con una captura más clara o escribe aquí las instrucciones si las tienes." rows={3}/></div>
        <div style={{marginBottom:12}}>
          <Label>¿Qué le cambiamos?</Label>
          <div style={{display:"flex",flexWrap:"wrap",gap:6,marginBottom:8}}>
            {QUICK.map((c)=><Pill key={c} active={changes.includes(c)} onClick={()=>toggleChange(c)}>{c}</Pill>)}
          </div>
          <GlassInput multiline value={custom} onChange={(e)=>setCustom(e.target.value)} placeholder="Cuéntame qué más necesitas — producto, texto, color, lo que sea" rows={2}/>
        </div>
        {refJson&&<p style={{fontFamily:"'Archivo',sans-serif",fontSize:12,color:"#7ec89a",margin:"0 0 12px"}}>✓ Se va a aplicar el estilo que analizamos arriba.</p>}
        <BtnPrimary disabled={!editImgApi||loadEdit} onClick={generateEdit}>{loadEdit?"⏳ Preparando tus instrucciones…":"Generar plantilla"}</BtnPrimary>
        {errEdit&&<p style={{color:"#ff8a8a",fontFamily:"'Archivo',sans-serif",fontSize:13,margin:"10px 0 0"}}>{errEdit}</p>}
        {editResult&&<div style={{marginTop:16,display:"flex",flexDirection:"column",gap:12}}>
          <div><Label>Reemplaza los espacios marcados con tus propios elementos y llévala a tu IA de confianza para crear una nueva imagen.</Label><CodeBlock text={editResult} maxH={180}/></div>
          <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
            <CopyBtn text={editResult} label="Copiar instrucciones"/>
            <SaveBtn saved={savedEdit} onSave={()=>{addEntry({id:uid(),tipo:"prompt",titulo:"Prompt "+new Date().toLocaleDateString("es-ES"),categoria:editCat,imagen:editImg,json_estilo:null,prompt_original:promptTxt||null,prompt_recreacion:editResult,createdAt:Date.now()});setSavedEdit(true);}}/>
          </div>
        </div>}
      </Step>
    </div>
  );
}

/* --- app root --- */
function App() {
  const [tab, setTab] = useState("banco");
  const [entries, setEntries] = useState([]);
  const [loaded, setLoaded] = useState(false);
  const [storageErr, setStorageErr] = useState(false);

  useEffect(() => {
    const link = document.createElement("link"); link.rel = "stylesheet"; link.href = FONT;
    document.head.appendChild(link);
  }, []);

  useEffect(() => {
    (async () => {
      try { const r = await window.storage.get(STORAGE_KEY); if (r?.value) setEntries(JSON.parse(r.value)); } catch {}
      setLoaded(true);
    })();
  }, []);

  const persist = useCallback(async (next) => {
    try { await window.storage.set(STORAGE_KEY, JSON.stringify(next)); setStorageErr(false); } catch { setStorageErr(true); }
  }, []);

  const addEntry = (e) => setEntries((p) => { const n=[e,...p]; persist(n); return n; });
  const importEntries = (arr) => setEntries((p) => { const n=[...arr,...p]; persist(n); return n; });
  const deleteEntry = (id) => setEntries((p) => { const n=p.filter((e)=>e.id!==id); persist(n); return n; });

  return (
    <div style={{ minHeight: "100vh", backgroundImage: `url(${BG})`, backgroundSize: "cover", backgroundPosition: "center top", backgroundAttachment: "fixed" }}>
      <style>{`
        @keyframes spin { to { transform: rotate(360deg); } }
        * { box-sizing: border-box; }
        input::placeholder, textarea::placeholder { color: rgba(244,238,227,0.3) !important; }
        ::-webkit-scrollbar { width: 5px; }
        ::-webkit-scrollbar-thumb { background: rgba(110,30,51,0.4); border-radius: 99px; }
      `}</style>
      <div style={{ position: "fixed", inset: 0, background: "rgba(20,8,5,0.62)", zIndex: 0, pointerEvents: "none" }} />
      <div style={{ position: "relative", zIndex: 1 }}>
        <header style={{ padding: "36px 24px 16px", maxWidth: 1200, margin: "0 auto" }}>
          <h1 style={{ margin: "0 0 6px", fontFamily: "'Archivo', sans-serif", fontWeight: 800, fontSize: "clamp(36px,7vw,64px)", letterSpacing: "-0.04em", lineHeight: 1, color: CREAM }}>
            MUSEMAP
          </h1>
          <p style={{ margin: "0 0 4px", fontFamily: "'Archivo', sans-serif", fontSize: "clamp(14px,2vw,17px)", color: CREAM, fontWeight: 500 }}>
            Convierte inspiración visual en dirección creativa.
          </p>
          <p style={{ margin: 0, fontFamily: "'Archivo', sans-serif", fontSize: 13, color: textMuted }}>
            Biblioteca inteligente de inspiración para crear con más claridad.
          </p>
        </header>
        <nav style={{ maxWidth: 1200, margin: "0 auto", padding: "12px 24px 20px", display: "flex", gap: 8, alignItems: "center" }}>
          {[{id:"banco",label:"Mi biblioteca"},{id:"asistente",label:"Analizar imagen"}].map((t) => (
            <Pill key={t.id} active={tab===t.id} onClick={()=>setTab(t.id)} vino={tab===t.id}>{t.label}</Pill>
          ))}
          {entries.length>0 && <span style={{ marginLeft: "auto", fontFamily: "'Archivo Narrow', sans-serif", fontSize: 11, color: textMuted }}>{entries.length} en tu biblioteca</span>}
        </nav>
        {storageErr && <div style={{ maxWidth: 1200, margin: "0 auto 12px", padding: "0 24px" }}><p style={{ background: "rgba(79,20,36,0.7)", backdropFilter: "blur(8px)", color: CREAM, padding: "10px 16px", fontFamily: "'Archivo', sans-serif", fontSize: 13, margin: 0, borderRadius: 12 }}>⚠ Tu biblioteca está casi llena. Elimina algunas en tu biblioteca para continuar.</p></div>}
        <main style={{ maxWidth: 1200, margin: "0 auto", padding: "0 24px 60px" }}>
          {!loaded
            ? <p style={{ fontFamily: "'Archivo', sans-serif", color: textMuted }}>Cargando tu biblioteca…</p>
            : tab==="banco"
              ? <Banco entries={entries} addEntry={addEntry} importEntries={importEntries} deleteEntry={deleteEntry} />
              : <Asistente addEntry={addEntry} />}
        </main>
      </div>
    </div>
  );
}


const _rootEl = document.getElementById("root");
ReactDOM.createRoot(_rootEl).render(React.createElement(App));
